function validate(input) {
  const [{ user_content = [] }] = input;
  const ids = new Set();
  for (const [id, text] of user_content) {
    if (id === null) return 'Every row needs a content_id.';
    if (ids.has(id)) return `content_id ${id} appears twice.`;
    ids.add(id);
    if (text === null || text.length === 0 || text.length > 255) return `content_text of row ${id} must be 1 to 255 characters.`;
    if (!/^[A-Za-z \\@\-\/^,]+$/.test(text)) return `content_text of row ${id} may hold only letters, spaces and \\ @ - / ^ ,`;
  }
  return null;
}

