function generate(rand, size) {
  const letters = ['hello', 'world', 'sql', 'the', 'quick', 'brown', 'data', 'a', 'top', 'rated', 'front', 'end', 'web', 'based', 'x'];
  const specials = ['\\', '@', '-', '/', '^', ','];
  const pick = list => list[Math.floor(rand() * list.length)];
  const casing = word => {
    const r = rand();
    if (r < 0.35) return word;
    if (r < 0.55) return word.toUpperCase();
    if (r < 0.7) return word[0].toUpperCase() + word.slice(1);
    return [...word].map(c => (rand() < 0.5 ? c.toUpperCase() : c)).join('');
  };
  // A word is plain, hyphenated, led by a special character, or has special characters inside or at the end.
  const word = () => {
    const r = rand();
    if (r < 0.35) return casing(pick(letters));
    if (r < 0.6) {
      const parts = 2 + Math.floor(rand() * 2), out = [];
      for (let i = 0; i < parts; i++) out.push(casing(pick(letters)));
      return out.join('-');
    }
    if (r < 0.75) return pick(specials) + casing(pick(letters));
    if (r < 0.9) return casing(pick(letters)) + pick(specials) + (rand() < 0.5 ? casing(pick(letters)) : '');
    return casing(pick(letters)) + '-' + (rand() < 0.5 ? '-' + casing(pick(letters)) : '');
  };
  const rows = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const user_content = [];
  let id = 0;
  for (let r = 0; r < rows; r++) {
    id += 1 + Math.floor(rand() * 3);
    const count = 1 + Math.floor(rand() * (size === 'small' ? 5 : 7));
    let text = '';
    for (let w = 0; w < count; w++) {
      if (w) text += rand() < 0.12 ? '  ' : ' ';
      text += word();
    }
    if (rand() < 0.1) text = ' ' + text;
    if (rand() < 0.1) text += ' ';
    user_content.push([id, text]);
  }
  return [{ user_content }];
}
